import sys
emb=open(sys.argv[1]).read()
lorem="Lorem ipsum dolor sit amet consectetur. Ac suspendisse elementum ornare tempor adipiscing nibh sit cras. "
items="";phones=""
for i in range(6):
    t=lorem*(2 if i%2 else 5)
    items+=f'''<div class="w-dyn-item"><article class="rating_card" data-review-card="true"><div class="rating_card_top">★★★★★ <span>Verifiziert</span></div><div class="rating_card_name">Vorname {i}</div><div class="rating_card_text" data-review-text="true"><ul id="list{i}"><li>{t}</li></ul></div><a class="rating_card_more" data-review-more="true" href="#" role="button">Weiterlesen</a><div class="rating_card_bottom"><div>12. Juni 2024</div><div>Trustpilot</div></div></article></div>'''
for i in range(5):
    phones+=f'<div class="w-dyn-item"><a class="review_phone" data-review-zoom="true" href="#" role="button" aria-label="zoom"><img class="review_phone_screen" alt="shot {i}" src="data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22213%22 height=%22448%22%3E%3Crect width=%22213%22 height=%22448%22 fill=%22%23{i}{i}{i}%22/%3E%3C/svg%3E"></a></div>'
css='''body{margin:0;background:#f5f0ee;font-family:sans-serif}.rating_card{display:flex;height:100%;padding:1.25rem;flex-direction:column;align-items:flex-start;border-radius:4px;background:#fafafa;row-gap:.5rem}.rating_card_text{font-size:.75rem;line-height:1.5}.rating_card_text ul{margin:0;padding:0;list-style:none}.rating_card_bottom{display:flex;width:100%;margin-top:auto;justify-content:space-between;font-size:.75rem}.reviews_marquee{display:flex;flex-direction:column;row-gap:3rem;padding-top:40px}.reviews_row_text{position:relative;overflow:hidden;padding-bottom:1.5rem}.reviews_track_text{display:grid;width:max-content;align-items:stretch;grid-auto-flow:column;grid-auto-columns:18.6875rem;column-gap:1.5rem}.reviews_row_phones{position:relative;padding:.5rem 0 2rem;overflow:hidden}.reviews_track_phones{display:flex;column-gap:1.5rem;width:max-content}.review_phone{display:block;width:213px}.review_phone img{display:block;width:100%}'''
print(f'''<!doctype html><html><head><style>{css}</style></head><body><a href="#" id="before">before</a><section data-reviews><div class="reviews_marquee"><div class="reviews_row_text"><div class="w-dyn-list"><div class="reviews_track_text w-dyn-items">{items}</div></div></div><div class="reviews_row_phones"><div class="w-dyn-list"><div class="reviews_track_phones w-dyn-items">{phones}</div></div></div></div><dialog class="reviews_dialog"><button class="reviews_dialog_close">x</button><div class="reviews_dialog_inner"><div class="reviews_dialog_body"></div><img class="reviews_dialog_image" alt="" hidden></div></dialog>{emb}</section><div style="height:1500px"></div></body></html>''')
